from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    result = []
    group = ""
    for char in paren_string:
        if char == "(":
            if group:
                result.append(group)
            group = "("
        elif char == ")":
            group += ")"
            result.append(group)
            group = ""
    return result  # Step 4: Return the separated groups as a list

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']
